//! OpenSSH integration, written by `massrelay install` alone. The running service never
//! changes the account's SSH configuration.
//!
//! The account's `~/.ssh/config` gets one `Include massrelay.d/*.conf` before its other
//! directives so an included host's explicit trust settings take precedence. Each profile has one generated file in `massrelay.d` that includes
//! `ssh-client.conf` from its private directory. The install creates that file empty; its
//! existence is what asks the runtime to fill it in.
//!
//! OpenSSH reads the fragments before the rest of the user's configuration and keeps the first
//! value it finds, so `ssh-client.conf` must put every setting under a `Host` line.
//!
//! Nothing is written through a link, no permission is changed to pass a check, and no file
//! the install did not generate is overwritten. The platform's file module holds the checks.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail, ensure};
use sha2::{Digest, Sha256};

#[cfg(windows)]
use crate::windows_service::ssh_files as files;
#[cfg(unix)]
mod unix;
#[cfg(unix)]
use unix as files;

use crate::private::cli;
use files::{Account, Found};

/// The OpenSSH configuration a profile's runtime writes, in the private profile directory.
pub const CLIENT_CONFIG: &str = "ssh-client.conf";
pub const CLIENT_STATE: &str = "ssh-client.json";
/// The directory beside `~/.ssh/config` holding one generated file for each profile.
const FRAGMENTS: &str = "massrelay.d";
/// Relative, as OpenSSH reads a path under `~/.ssh` in the user's configuration. It finds
/// that `~` through `HOME`, so an `ssh` run with another `HOME` does not see the profiles.
const PATTERN: &str = "massrelay.d/*.conf";
const GENERATED: &str = "# Generated by massrelay install\n";
const BOM: &[u8] = b"\xef\xbb\xbf";
/// How often a file that changes while it is being replaced is read again.
const ATTEMPTS: usize = 3;

/// Connect this account's OpenSSH to the profile in `state_dir`, the canonical path its
/// service was just installed for.
pub fn register(state_dir: &Path) -> Result<()> {
    let config = check_openssh()
        .and_then(|()| Account::current())
        .and_then(|account| integrate(&account, &account.home()?, state_dir))
        .context(
            "the background service is installed and running, but OpenSSH is not set up for \
             it. Correct this and run 'massrelay install' again",
        )?;
    println!("SSH config      {}", config.display());
    Ok(())
}

/// Managed entries disable the user's fallback host-key command explicitly. Never make an
/// older system client parse a keyword it cannot recognize, even for an unrelated host.
fn check_openssh() -> Result<()> {
    let output = std::process::Command::new(crate::private::ssh::openssh("ssh")?)
        .arg("-V")
        .output()
        .context("check the system OpenSSH client")?;
    ensure!(
        output.status.success(),
        "could not check the system OpenSSH version"
    );
    let text = String::from_utf8_lossy(&output.stderr);
    let version = text
        .trim_start()
        .strip_prefix("OpenSSH_for_Windows_")
        .or_else(|| text.trim_start().strip_prefix("OpenSSH_"));
    let supported = version
        .and_then(|version| version.split_once('.'))
        .and_then(|(major, minor)| {
            Some((
                major.parse::<u32>().ok()?,
                minor
                    .split(|c: char| !c.is_ascii_digit())
                    .next()?
                    .parse::<u32>()
                    .ok()?,
            ))
        })
        .is_some_and(|version| version >= (8, 5));
    ensure!(
        supported,
        "managed SSH config requires OpenSSH 8.5 or later"
    );
    Ok(())
}

/// `register` for the account whose home directory is `home`. Returns its SSH configuration.
pub(crate) fn integrate(account: &Account, home: &Path, state_dir: &Path) -> Result<PathBuf> {
    ensure!(
        files::canonical(state_dir)? == state_dir,
        "{} was replaced while it was being installed",
        state_dir.display()
    );
    let profile = state_dir.join(cli::DIR_NAME);
    account.profile_directory(&profile)?;
    let client = profile.join(CLIENT_CONFIG);
    let (name, fragment) = fragment(&client)?;
    // An existing file that must not be included stops the install before anything changes.
    if let Some(found) = account.read(&client)? {
        account.check_client(&client, &found)?;
    }

    account.home_directory(home)?;
    let ssh = home.join(".ssh");
    account.ssh_directory(&ssh)?;
    let fragments = ssh.join(FRAGMENTS);
    account.fragment_directory(&fragments)?;
    let _lock = account.lock(&fragments.join(".lock"))?;

    let target = fragments.join(name);
    let generated = |found: &Found| -> Result<()> {
        account.check_fragment(&target, found)?;
        ensure!(
            found.contents.starts_with(GENERATED.as_bytes()),
            "{} was not generated by massrelay install; it was not changed",
            target.display()
        );
        Ok(())
    };
    let existing = account.read(&target)?;
    if let Some(found) = &existing {
        generated(found)?;
    }
    let namespace = reserve_namespace(account, &fragments, &target)?;
    let state = profile.join(CLIENT_STATE);
    update(account, &state, |found| match found {
        Some(found) => {
            account.check_client(&state, found)?;
            let saved: serde_json::Value = serde_json::from_slice(&found.contents)
                .context("read the profile's SSH alias reservations")?;
            ensure!(
                saved.get("namespace").and_then(serde_json::Value::as_u64) == Some(namespace),
                "the profile's SSH alias namespace has changed"
            );
            Ok(None)
        }
        None => {
            ensure!(
                existing.is_none(),
                "the profile's SSH alias reservations are missing"
            );
            Ok(Some(serde_json::to_vec(&serde_json::json!({
                "namespace": namespace,
                "names": {},
                "hosts": {},
            }))?))
        }
    })?;

    let config = ssh.join("config");
    update(account, &config, |found| match found {
        Some(found) => match include_position(&found.contents, &ssh) {
            IncludePosition::First => Ok(None),
            IncludePosition::Later => {
                bail!("the MassRelay Include follows another global SSH directive")
            }
            IncludePosition::Absent => with_include(&found.contents).map(Some),
        },
        None => with_include(b"").map(Some),
    })
    // Said for a configuration this will not write, such as a link into a dotfile tree.
    .with_context(|| {
        format!(
            "put 'Include {PATTERN}' before any other directive in {}",
            config.display()
        )
    })?;
    update(account, &target, |found| {
        if let Some(found) = found {
            generated(found)?;
            if found.contents == fragment.as_bytes() {
                return Ok(None);
            }
        }
        Ok(Some(fragment.clone().into_bytes()))
    })?;
    // Last: the runtime writes the file once it exists, and by now ssh reads it.
    update(account, &client, |found| match found {
        Some(found) => account.check_client(&client, found).map(|()| None),
        None => Ok(Some(Vec::new())),
    })?;
    Ok(config)
}

/// The install lock makes allocations account-wide and durable. Only the first profile
/// can use bare peer names. Other profiles reserve a disjoint numeric suffix.
fn reserve_namespace(account: &Account, dir: &Path, profile: &Path) -> Result<u64> {
    let ledger = dir.join(".namespaces.json");
    let name = profile
        .file_name()
        .and_then(|name| name.to_str())
        .context("invalid profile name")?;
    let mut namespace = None;
    update(account, &ledger, |found| {
        let mut reservations: BTreeMap<String, u64> = match found {
            Some(found) => {
                account.check_fragment(&ledger, found)?;
                serde_json::from_slice(&found.contents).context("read SSH profile namespaces")?
            }
            None => BTreeMap::new(),
        };
        for entry in std::fs::read_dir(dir)? {
            let path = entry?.path();
            if path.extension().is_some_and(|ext| ext == "conf") {
                let name = path.file_name().and_then(|name| name.to_str());
                ensure!(
                    name.is_some_and(|name| reservations.contains_key(name)),
                    "the SSH profile namespace ledger does not cover {}",
                    path.display()
                );
            }
        }
        let unique: std::collections::BTreeSet<_> = reservations.values().copied().collect();
        ensure!(
            !unique.contains(&0) && unique.len() == reservations.len(),
            "invalid SSH profile namespace ledger"
        );
        if let Some(assigned) = reservations.get(name) {
            namespace = Some(*assigned);
            return Ok(None);
        }
        let next = reservations
            .values()
            .max()
            .copied()
            .unwrap_or(0)
            .checked_add(1)
            .context("SSH profile namespace exhausted")?;
        namespace = Some(next);
        reservations.insert(name.to_owned(), next);
        Ok(Some(serde_json::to_vec(&reservations)?))
    })?;
    namespace.context("no SSH profile namespace was reserved")
}

/// Bring a file to what `change` makes of it, where `None` leaves it as it is. A file that
/// changes or appears meanwhile is read again, never overwritten with an older reading.
fn update(
    account: &Account,
    path: &Path,
    mut change: impl FnMut(Option<&Found>) -> Result<Option<Vec<u8>>>,
) -> Result<()> {
    for _ in 0..ATTEMPTS {
        let found = account.read(path)?;
        let Some(contents) = change(found.as_ref())? else {
            return Ok(());
        };
        let written = match &found {
            Some(found) => account.replace(path, found, &contents)?,
            None => account.create(path, &contents)?,
        };
        if written {
            return Ok(());
        }
    }
    bail!(
        "{} kept changing while it was being updated",
        path.display()
    )
}

/// The name and contents of the file that points SSH at a profile's `client` configuration.
fn fragment(client: &Path) -> Result<(String, String)> {
    let text = client
        .to_str()
        .with_context(|| format!("path is not Unicode: {}", client.display()))?;
    #[cfg(windows)]
    let text = &text.replace('\\', "/");
    // OpenSSH expands or globs these in an Include, or ends the argument at them.
    ensure!(
        !text
            .chars()
            .any(|c| c.is_control() || "\"\\%$*?[]{}".contains(c)),
        "OpenSSH cannot include {text}; use a state directory whose path has none of \
         \" \\ % $ * ? [ ] {{ }}"
    );
    Ok((
        format!("{:x}.conf", Sha256::digest(text.as_bytes())),
        format!("{GENERATED}Include \"{text}\"\n"),
    ))
}

#[derive(Debug, PartialEq, Eq)]
enum IncludePosition {
    First,
    Later,
    Absent,
}

/// A managed block must precede other global settings to enforce its host pin.
fn include_position(config: &[u8], ssh: &Path) -> IncludePosition {
    let separators = |text: &str| {
        if cfg!(windows) {
            text.replace('\\', "/")
        } else {
            text.to_owned()
        }
    };
    let absolute = separators(&format!("{}/{PATTERN}", ssh.display()));
    let config = config.strip_prefix(BOM).unwrap_or(config);
    let mut first = true;
    for line in config.split(|&byte| byte == b'\n') {
        let line = String::from_utf8_lossy(line);
        let (keyword, arguments) = directive(&line);
        if keyword.is_empty() || keyword.starts_with('#') {
            continue;
        }
        if keyword.eq_ignore_ascii_case("host") || keyword.eq_ignore_ascii_case("match") {
            break;
        }
        if keyword.eq_ignore_ascii_case("include") {
            for (index, word) in words(arguments).iter().enumerate() {
                let word = separators(word);
                if word == PATTERN || word == format!("~/.ssh/{PATTERN}") || word == absolute {
                    return if first && index == 0 {
                        IncludePosition::First
                    } else {
                        IncludePosition::Later
                    };
                }
            }
        }
        first = false;
    }
    IncludePosition::Absent
}

/// A line's keyword and what follows it, split as OpenSSH splits them.
fn directive(line: &str) -> (&str, &str) {
    let line = line.trim_start();
    let (keyword, rest) = match line.strip_prefix('"') {
        Some(quoted) => quoted.split_once('"').unwrap_or((quoted, "")),
        None => {
            let end = line
                .find(|c: char| c.is_whitespace() || c == '=' || c == '"')
                .unwrap_or(line.len());
            line.split_at(end)
        }
    };
    let rest = rest.trim_start();
    (keyword, rest.strip_prefix('=').unwrap_or(rest))
}

/// The arguments of a line: separated by blanks, optionally quoted, ending at a comment.
fn words(arguments: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut word: Option<String> = None;
    let mut quote = None;
    for c in arguments.chars() {
        match quote {
            Some(open) if c == open => quote = None,
            None if c == '"' || c == '\'' => {
                quote = Some(c);
                word.get_or_insert_default();
            }
            None if c.is_whitespace() => words.extend(word.take()),
            None if c == '#' && word.is_none() => break,
            _ => word.get_or_insert_default().push(c),
        }
    }
    words.extend(word);
    words
}

/// The configuration with the include ahead of everything in it, which is otherwise unchanged,
/// byte order mark first and in its own line endings.
fn with_include(config: &[u8]) -> Result<Vec<u8>> {
    ensure!(
        !config.contains(&0),
        "it is not plain text (UTF-16 perhaps); save it as UTF-8"
    );
    let (mark, body) = match config.strip_prefix(BOM) {
        Some(body) => (BOM, body),
        None => (&[][..], config),
    };
    let newline = match body.iter().position(|&byte| byte == b'\n') {
        Some(end) if body[..end].ends_with(b"\r") => "\r\n",
        _ => "\n",
    };
    let mut updated = mark.to_vec();
    updated.extend(
        format!("# Added by massrelay install{newline}Include {PATTERN}{newline}").into_bytes(),
    );
    if !body.is_empty() {
        updated.extend_from_slice(newline.as_bytes());
        updated.extend_from_slice(body);
    }
    Ok(updated)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn only_an_include_that_applies_to_every_host_counts() {
        let ssh = Path::new("/home/someone/.ssh");
        for present in [
            "Include massrelay.d/*.conf",
            "\u{feff}include=massrelay.d/*.conf\r\n",
            "Include = ~/.ssh/massrelay.d/*.conf\nHost a\n",
            "Include '/home/someone/.ssh/massrelay.d/*.conf'",
            "# Host commented\nInclude massrelay.d/*.conf",
        ] {
            assert_eq!(
                include_position(present.as_bytes(), ssh),
                IncludePosition::First
            );
        }
        for later in [
            "StrictHostKeyChecking no\nInclude massrelay.d/*.conf",
            "Include other massrelay.d/*.conf",
        ] {
            assert_eq!(
                include_position(later.as_bytes(), ssh),
                IncludePosition::Later
            );
        }
        for absent in [
            "",
            "# Include massrelay.d/*.conf",
            "Include other # massrelay.d/*.conf",
            "Include massrelay.d/other.conf",
            "Host a\n  Include massrelay.d/*.conf",
            "\tmatch all\nInclude massrelay.d/*.conf",
            "Host=a\nInclude massrelay.d/*.conf",
            "\"Host\" a\nInclude massrelay.d/*.conf",
        ] {
            assert_eq!(
                include_position(absent.as_bytes(), ssh),
                IncludePosition::Absent
            );
        }
    }

    #[test]
    fn adding_the_include_keeps_every_byte_and_the_line_endings() -> Result<()> {
        // Latin-1 in a comment, CRLF and no final newline.
        let original = b"\xef\xbb\xbf# caf\xe9\r\nUser a\r\nHost b\r\n  Port 1";
        let updated = with_include(original)?;
        let added = b"# Added by massrelay install\r\nInclude massrelay.d/*.conf\r\n\r\n";
        assert_eq!(updated, [BOM, added, &original[BOM.len()..]].concat());
        assert_eq!(
            include_position(&updated, Path::new("/h/.ssh")),
            IncludePosition::First
        );
        assert!(!with_include(b"User a\n")?.contains(&b'\r'));
        assert!(with_include(b"\xff\xfeH\0o\0").is_err());
        Ok(())
    }
}

